-- ============================================================
-- Testes: 20270120200000_catalogo_resguardos_mudelar.sql (base RH)
-- Ficheiro GERADO por script (gerar.js) a partir do Excel Resguardos.xlsx, como a migration.
-- ============================================================
-- ORDEM: correr ANTES do db push da 20270120200000 (falha no passo 0: a subcategoria «Resguardos de Duche» da Mudelar
-- não tem produtos); depois do push termina com «OK: …». Qualquer falha: 'FALHOU: …'.
--
-- SÓ LEITURA, dentro de BEGIN … ROLLBACK. Não escreve em nenhuma organização. Lê a Mudelar
-- (3242e925-da26-459a-8258-be04d904e355) e, para provar que nada foi escrito fora dela, as outras organizações (só
-- contagens pelo xmin da transação da importação). Para comparar 20 SKUs com cat_prever_sku_modelo usa, só nesta
-- transação, as claims de um membro ativo da Mudelar com products.edit (a função é só de leitura). Nenhuma chamada
-- recusada de propósito. Não assume que a Largura, as suas opções ou o Acabamento não existiam antes (outras importações
-- podem tê-los criado).
--
-- Correr a partir do worktree rh-pessoas (supabase/.temp/project-ref = uetjghdkwbywbftedtth):
--   supabase db query --linked -f supabase/tests/catalogo_resguardos_mudelar.test.sql
--
-- O que PROVA:
--   1. 2541 produtos vivos na subcategoria (das 2561 linhas do Excel ficam de fora 20), 558 modelos
--      com os números 1..558, cada um com os seus produtos.
--   2. Cada produto como a sua linha do Excel: nome, modelo, estado (311 rascunhos), Cor (2521), Largura (1883),
--      Medida 2D (620, com intervalos {de, ate} onde o Excel os tem), Acabamento Frost Plus (397) e só esses atributos.
--   3. Preços: 2253 com custo e PVP (IVA 23), 288 sem preço (e com « (sem preço)» no nome).
--   4. SKUs exatos para 7 exemplos, todos únicos, gerados e no formato DB-RD-NNNN-….
--   5. Fornecedor Anlorbel (o que já existia) ligado a cada produto: preferido, preço = custo, supplier_sku = código do
--      fornecedor (2486) ou o SKU; marca GME; unidade un.
--   6. O atributo Acabamento (lista, entra no SKU) com Transparente e Frost Plus; as opções de Largura usadas com sigla.
--   7. Nenhuma linha de outra organização tem o xmin da transação que criou os produtos.
--   8. 20 produtos ao acaso: cat_prever_sku_modelo dá o SKU gravado, sem faltas.
--   9. A linha consolidada da auditoria (source migration:resguardos_mudelar).
-- O que NÃO cobre: o ecrã (a Medida com intervalo precisa do ecrã que a mostra); as escritas por produto que a auditoria
-- deixou de registar (bypass, de propósito).
-- ============================================================

BEGIN;

-- ─── 0. A importação foi aplicada? ───────────────────────────────────────────
DO $t0$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM products p JOIN product_categories s ON s.id = p.subcategory_id
                 WHERE p.organization_id = '3242e925-da26-459a-8258-be04d904e355' AND NOT p.is_deleted
                   AND s.organization_id = '3242e925-da26-459a-8258-be04d904e355'
                   AND public.fn_cat_chave_opcao(s.name) = 'resguardos de duche') THEN
    RAISE EXCEPTION 'FALHOU: passo 0 — a subcategoria «Resguardos de Duche» da Mudelar não tem produtos (aplicar 20270120200000).';
  END IF;
END $t0$;

-- ─── 1 a 9 ──────────────────────────────────────────────────────────────────
DO $t$
DECLARE
  c_org constant uuid := '3242e925-da26-459a-8258-be04d904e355';
  c_total constant integer := 2541;
  c_n_modelos constant integer := 558;
  c_iva constant numeric := 23;
  v_cat uuid; v_sub uuid; v_a_cor uuid; v_a_med uuid; v_a_larg uuid; v_a_acab uuid; v_g_cor uuid; v_g_larg uuid; v_g_acab uuid;
  v_sup uuid; v_marca uuid; v_frost uuid;
  v_n bigint; v_m bigint; v_k bigint; v_txt text; v_xid text; v_auth uuid; v_prev jsonb; v_attrs jsonb; r record;
BEGIN
  SELECT c.id INTO v_cat FROM product_categories c
  WHERE c.organization_id = c_org AND c.parent_id IS NULL AND c.deleted_at IS NULL AND public.fn_cat_chave_opcao(c.name) = 'duche & banho';
  SELECT c.id INTO v_sub FROM product_categories c
  WHERE c.organization_id = c_org AND c.parent_id = v_cat AND c.deleted_at IS NULL AND public.fn_cat_chave_opcao(c.name) = 'resguardos de duche';
  SELECT a.id INTO v_a_cor FROM product_attributes a WHERE a.organization_id = c_org AND a.deleted_at IS NULL AND a.code::text = 'cor';
  SELECT a.id INTO v_a_med FROM product_attributes a WHERE a.organization_id = c_org AND a.deleted_at IS NULL AND a.code::text = 'medida';
  SELECT a.id INTO v_a_larg FROM product_attributes a WHERE a.organization_id = c_org AND a.deleted_at IS NULL
    AND (a.code::text = 'largura' OR public.fn_cat_chave_opcao(a.label::text) = 'largura');
  SELECT a.id INTO v_a_acab FROM product_attributes a WHERE a.organization_id = c_org AND a.deleted_at IS NULL
    AND (a.code::text = 'acabamento' OR public.fn_cat_chave_opcao(a.label::text) = 'acabamento');
  v_g_cor := public.fn_cat_grupo_do_atributo(v_a_cor, c_org);
  v_g_larg := public.fn_cat_grupo_do_atributo(v_a_larg, c_org);
  v_g_acab := public.fn_cat_grupo_do_atributo(v_a_acab, c_org);
  SELECT v.id INTO v_frost FROM attribute_option_group_values v WHERE v.group_id = v_g_acab AND public.fn_cat_chave_opcao(v.value_text::text) = 'frost plus';
  IF v_sub IS NULL OR v_a_cor IS NULL OR v_a_med IS NULL OR v_a_larg IS NULL OR v_a_acab IS NULL OR v_frost IS NULL THEN
    RAISE EXCEPTION 'FALHOU: configuração da Mudelar incompleta (subcategoria, Cor, Medida, Largura, Acabamento ou Frost Plus).';
  END IF;

  CREATE TEMP TABLE _t_linhas (linha integer PRIMARY KEY, modelo smallint, cor text, largura text, medida smallint, frost boolean,
                               nome text, status text, custo numeric, pvp numeric, cod_forn text) ON COMMIT DROP;
  CREATE TEMP TABLE _t_medidas (id smallint PRIMARY KEY, largura jsonb, comprimento jsonb) ON COMMIT DROP;
  CREATE TEMP TABLE _t_cores (nome_excel text PRIMARY KEY, nome_mudelar text) ON COMMIT DROP;

  -- 1. quantos e os modelos
  SELECT count(*) INTO v_n FROM products p WHERE p.organization_id = c_org AND p.subcategory_id = v_sub AND NOT p.is_deleted;
  IF v_n <> c_total THEN RAISE EXCEPTION 'FALHOU: passo 1 — % produtos em vez de %.', v_n, c_total; END IF;
  SELECT count(*), count(DISTINCT pm.numero), max(pm.numero), count(*) FILTER (WHERE NOT pm.is_active) INTO v_n, v_m, v_k, v_txt
  FROM product_models pm WHERE pm.organization_id = c_org AND pm.subcategory_id = v_sub AND pm.deleted_at IS NULL;
  IF v_n <> c_n_modelos OR v_m <> c_n_modelos OR v_k <> c_n_modelos OR v_txt <> '0' THEN
    RAISE EXCEPTION 'FALHOU: passo 1 — % modelos (% números, maior %, % desativados) em vez de % (1..%).', v_n, v_m, v_k, v_txt, c_n_modelos, c_n_modelos;
  END IF;
  SELECT count(*) INTO v_n FROM product_models pm
  WHERE pm.organization_id = c_org AND pm.subcategory_id = v_sub AND pm.deleted_at IS NULL
    AND NOT EXISTS (SELECT 1 FROM products p WHERE p.model_id = pm.id AND NOT p.is_deleted);
  IF v_n > 0 THEN RAISE EXCEPTION 'FALHOU: passo 1 — % modelos sem produtos.', v_n; END IF;

  -- 2 e 3. cada produto como a sua linha (pelo nome, que é único)
  SELECT count(*), string_agg(l.linha::text, ', ') INTO v_n, v_txt
  FROM _t_linhas l
  LEFT JOIN products p ON p.organization_id = c_org AND p.subcategory_id = v_sub AND NOT p.is_deleted AND p.name = l.nome
  LEFT JOIN product_models pm ON pm.id = p.model_id
  LEFT JOIN _t_cores tc ON tc.nome_excel = l.cor
  LEFT JOIN _t_medidas tm ON tm.id = l.medida
  LEFT JOIN product_attribute_values vc ON vc.product_id = p.id AND vc.attribute_id = v_a_cor
  LEFT JOIN product_attribute_values vl ON vl.product_id = p.id AND vl.attribute_id = v_a_larg
  LEFT JOIN product_attribute_values vm ON vm.product_id = p.id AND vm.attribute_id = v_a_med
  LEFT JOIN product_attribute_values va ON va.product_id = p.id AND va.attribute_id = v_a_acab
  LEFT JOIN product_prices pc ON pc.product_id = p.id AND pc.price_type = 'purchase'
  LEFT JOIN product_prices pv ON pv.product_id = p.id AND pv.price_type = 'retail'
  WHERE NOT coalesce(
        pm.numero = l.modelo AND pm.subcategory_id = v_sub AND p.status::text = l.status
        AND public.fn_cat_chave_opcao(vc.value_text) IS NOT DISTINCT FROM public.fn_cat_chave_opcao(tc.nome_mudelar)
        AND vl.value_text IS NOT DISTINCT FROM l.largura
        AND (vm.value_json -> 'largura') IS NOT DISTINCT FROM tm.largura AND (vm.value_json -> 'comprimento') IS NOT DISTINCT FROM tm.comprimento
        AND (vm.product_id IS NULL OR (vm.value_json ->> 'tipo' = '2D' AND vm.unit = 'cm' AND vm.value_json ->> 'unidade' = 'cm'
                                       AND public.fn_cat_medida_ler(vm.value_json, vm.unit) IS NOT NULL
                                       AND vm.value_text = public.fn_cat_dimensao_texto(vm.value_json -> 'largura') || ' × '
                                                           || public.fn_cat_dimensao_texto(vm.value_json -> 'comprimento') || ' cm'))
        AND (va.product_id IS NOT NULL) = l.frost AND (va.product_id IS NULL OR public.fn_cat_chave_opcao(va.value_text) = 'frost plus')
        AND (SELECT count(*) FROM product_attribute_values x WHERE x.product_id = p.id)
            = (CASE WHEN l.cor IS NULL THEN 0 ELSE 1 END) + (CASE WHEN l.largura IS NULL THEN 0 ELSE 1 END)
              + (CASE WHEN l.medida IS NULL THEN 0 ELSE 1 END) + (CASE WHEN l.frost THEN 1 ELSE 0 END)
        AND pc.price IS NOT DISTINCT FROM round(l.custo, 2) AND pc.preco_exato IS NOT DISTINCT FROM round(l.custo, 6)
        AND pv.price IS NOT DISTINCT FROM round(l.pvp, 2)
        AND (pc.product_id IS NULL OR (pc.vat_rate = c_iva AND pc.currency = 'EUR'))
        AND (pv.product_id IS NULL OR (pv.vat_rate = c_iva AND pv.currency = 'EUR'))
        AND (SELECT count(*) FROM product_prices x WHERE x.product_id = p.id) = (CASE WHEN l.custo IS NULL THEN 0 ELSE 2 END)
        AND (l.custo IS NOT NULL) = (p.name NOT LIKE '% (sem preço)'),
        false);
  IF v_n > 0 THEN RAISE EXCEPTION 'FALHOU: passos 2-3 — % produtos diferentes da sua linha do Excel (linhas %).', v_n, left(v_txt, 800); END IF;

  -- 4. SKUs exatos, únicos e no formato
  SELECT string_agg(e.nome || ': ' || coalesce(p.sku, 'sem produto') || ' em vez de ' || e.sku, '; ') INTO v_txt
  FROM (VALUES ('Resguardo Kenna 1 fijo + 1 corredera 100 Cromo', 'DB-RD-0001-CRO-100'), ('Resguardo Kenna 1 fijo + 1 corredera 100 Negro', 'DB-RD-0001-NG-100'), ('Resguardo Banheira Combi K 2 Puertas Abativeis ao Vertice 83,5-85,5/48,5-50,5 Cromo', 'DB-RD-0510-CRO-83P5A85P5X48P5A50P5'), ('Resguardo Kenna Angular ao vertice 70x70 Cromo', 'DB-RD-0020-CRO-70X70'), ('Resguardo Basic Frontal 1F1C 95-100 Frost Plus Cromo', 'DB-RD-0024-CRO-95A100-FP'), ('Resguardo Glass Bisagra a Pared Combi 1 70 Blanco', 'DB-RD-0473-B-70'), ('Resguardo Combi (A/C/H) Frost Plus Acessório Perfil compensação +3cm Frost Plus Genérico', 'DB-RD-0363-FP')) AS e(nome, sku)
  LEFT JOIN products p ON p.organization_id = c_org AND p.subcategory_id = v_sub AND NOT p.is_deleted AND p.name = e.nome
  WHERE p.sku IS DISTINCT FROM e.sku;
  IF v_txt IS NOT NULL THEN RAISE EXCEPTION 'FALHOU: passo 4 — SKUs: %', v_txt; END IF;
  SELECT count(DISTINCT p.sku), count(*) FILTER (WHERE p.sku !~ '^DB-RD-[0-9]{4}(-[A-Z0-9]+){0,4}$' OR NOT p.sku_gerado)
    INTO v_n, v_m
  FROM products p WHERE p.organization_id = c_org AND p.subcategory_id = v_sub AND NOT p.is_deleted;
  IF v_n <> c_total OR v_m > 0 THEN
    RAISE EXCEPTION 'FALHOU: passo 4 — % SKUs distintos (esperados %), % fora do formato DB-RD-NNNN-… ou não gerados.', v_n, c_total, v_m;
  END IF;

  -- 5. fornecedor, marca, unidade
  SELECT count(*), (array_agg(s.id))[1] INTO v_n, v_sup FROM suppliers s
  WHERE s.organization_id = c_org AND s.deleted_at IS NULL
    AND public.fn_cat_chave_opcao(s.name) = public.fn_cat_chave_opcao('ANLORBEL COMERCIO MATERIAIS CONSTRUCAO E DECORACAO');
  IF v_n <> 1 THEN RAISE EXCEPTION 'FALHOU: passo 5 — % fornecedores Anlorbel na Mudelar (esperado 1).', v_n; END IF;
  SELECT b.id INTO v_marca FROM brands b WHERE b.organization_id = c_org AND b.deleted_at IS NULL AND b.name = 'GME';
  SELECT count(*) INTO v_n
  FROM _t_linhas l
  LEFT JOIN products p ON p.organization_id = c_org AND p.subcategory_id = v_sub AND NOT p.is_deleted AND p.name = l.nome
  WHERE NOT coalesce(p.supplier_id = v_sup AND p.fornecedor_livre = 'ANLORBEL COMERCIO MATERIAIS CONSTRUCAO E DECORACAO'
                     AND p.brand_id = v_marca AND p.marca_livre = 'GME' AND p.unidade = 'un' AND p.uom_id IS NOT NULL
                     AND p.tipo_catalogo = 'produto' AND p.category_id = v_cat AND p.manages_stock AND p.is_active
                     AND (SELECT count(*) FROM item_suppliers i WHERE i.product_id = p.id AND i.deleted_at IS NULL) = 1
                     AND EXISTS (SELECT 1 FROM item_suppliers i
                                 WHERE i.product_id = p.id AND i.deleted_at IS NULL AND i.supplier_id = v_sup AND i.is_preferred AND i.is_active
                                   AND i.organization_id = c_org AND i.supplier_sku = coalesce(l.cod_forn, p.sku)
                                   AND i.purchase_price IS NOT DISTINCT FROM round(l.custo, 2)),
                     false);
  IF v_n > 0 THEN RAISE EXCEPTION 'FALHOU: passo 5 — % produtos sem o fornecedor, a marca, a unidade ou o código do fornecedor certos.', v_n; END IF;

  -- 6. Acabamento e siglas da Largura
  IF NOT EXISTS (SELECT 1 FROM product_attributes a WHERE a.id = v_a_acab AND NOT a.is_measurement AND a.sku_entra AND a.sku_ordem IS NOT NULL)
     OR (SELECT count(*) FROM attribute_option_group_values v WHERE v.group_id = v_g_acab AND v.is_active AND v.sigla IS NOT NULL
           AND public.fn_cat_chave_opcao(v.value_text::text) IN ('transparente', 'frost plus')) <> 2 THEN
    RAISE EXCEPTION 'FALHOU: passo 6 — o Acabamento não é de lista, não entra no SKU, ou faltam Transparente/Frost Plus com sigla.';
  END IF;
  SELECT count(*) INTO v_n FROM (SELECT DISTINCT l.largura FROM _t_linhas l WHERE l.largura IS NOT NULL) x
  WHERE NOT EXISTS (SELECT 1 FROM attribute_option_group_values v WHERE v.group_id = v_g_larg AND v.value_text = x.largura
                    AND v.is_active AND v.sigla ~ '^[A-Z0-9]{1,6}$');
  IF v_n > 0 THEN RAISE EXCEPTION 'FALHOU: passo 6 — % opções de Largura usadas sem opção ativa com sigla.', v_n; END IF;

  -- 7. nada escrito fora da Mudelar: as linhas de outras organizações não têm o xmin da transação da importação
  SELECT mode() WITHIN GROUP (ORDER BY p.xmin::text) INTO v_xid FROM products p
  WHERE p.organization_id = c_org AND p.subcategory_id = v_sub AND NOT p.is_deleted;
  SELECT string_agg(x.t || ' ' || x.n, ', ') INTO v_txt FROM (
    SELECT 'products' AS t, count(*) AS n FROM products p WHERE p.xmin::text = v_xid AND p.organization_id IS DISTINCT FROM c_org
    UNION ALL SELECT 'product_prices', count(*) FROM product_prices x JOIN products p ON p.id = x.product_id
              WHERE x.xmin::text = v_xid AND p.organization_id IS DISTINCT FROM c_org
    UNION ALL SELECT 'product_attribute_values', count(*) FROM product_attribute_values x JOIN products p ON p.id = x.product_id
              WHERE x.xmin::text = v_xid AND p.organization_id IS DISTINCT FROM c_org
    UNION ALL SELECT 'product_organizations', count(*) FROM product_organizations x WHERE x.xmin::text = v_xid AND x.organization_id IS DISTINCT FROM c_org
    UNION ALL SELECT 'item_suppliers', count(*) FROM item_suppliers x WHERE x.xmin::text = v_xid AND x.organization_id IS DISTINCT FROM c_org
    UNION ALL SELECT 'product_models', count(*) FROM product_models x WHERE x.xmin::text = v_xid AND x.organization_id IS DISTINCT FROM c_org
    UNION ALL SELECT 'product_attributes', count(*) FROM product_attributes x WHERE x.xmin::text = v_xid AND x.organization_id IS DISTINCT FROM c_org
    UNION ALL SELECT 'attribute_option_group_values', count(*) FROM attribute_option_group_values v JOIN attribute_option_groups g ON g.id = v.group_id
              WHERE v.xmin::text = v_xid AND g.organization_id IS DISTINCT FROM c_org) x
  WHERE x.n > 0;
  IF v_txt IS NOT NULL THEN RAISE EXCEPTION 'FALHOU: passo 7 — linhas de outras organizações escritas pela importação: %', v_txt; END IF;
  SELECT count(*) INTO v_n FROM products p
  WHERE p.organization_id IS DISTINCT FROM c_org
    AND (p.subcategory_id = v_sub OR p.model_id IN (SELECT pm.id FROM product_models pm WHERE pm.organization_id = c_org AND pm.subcategory_id = v_sub));
  IF v_n > 0 THEN RAISE EXCEPTION 'FALHOU: passo 7 — % produtos de outras organizações apontam para a subcategoria ou modelos da Mudelar.', v_n; END IF;

  -- 8. 20 ao acaso: cat_prever_sku_modelo (só leitura) como um membro da Mudelar com products.edit
  SELECT u.auth_user_id INTO v_auth
  FROM anew_memberships m JOIN anew_users u ON u.id = m.user_id AND u.deleted_at IS NULL AND u.auth_user_id IS NOT NULL
  WHERE m.organization_id = c_org AND m.status = 'active' AND m.end_date IS NULL AND NOT coalesce(m.role_is_client, false)
    AND public.has_anew_permission_in_org(u.auth_user_id, 'products.edit', c_org)
  ORDER BY m.created_at, u.id LIMIT 1;
  IF v_auth IS NULL THEN RAISE EXCEPTION 'FALHOU: passo 8 — sem membro ativo da Mudelar com products.edit.'; END IF;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', v_auth, 'role', 'authenticated')::text, true);
  v_n := 0;
  FOR r IN SELECT p.id, p.sku, p.model_id FROM products p
           WHERE p.organization_id = c_org AND p.subcategory_id = v_sub AND NOT p.is_deleted ORDER BY random() LIMIT 20 LOOP
    SELECT coalesce(jsonb_agg(CASE WHEN a.is_measurement THEN jsonb_build_object('atributo', v.attribute_id, 'medida', v.value_json)
                                   ELSE jsonb_build_object('atributo', v.attribute_id, 'opcao', o.id) END), '[]'::jsonb)
      INTO v_attrs
    FROM product_attribute_values v
    JOIN product_attributes a ON a.id = v.attribute_id
    LEFT JOIN attribute_option_group_values o
      ON NOT a.is_measurement AND o.group_id = public.fn_cat_grupo_do_atributo(a.id, c_org) AND o.value_text = v.value_text
    WHERE v.product_id = r.id;
    v_prev := public.cat_prever_sku_modelo(c_org, v_cat, v_sub, r.model_id, v_attrs, r.id);
    IF (v_prev ->> 'sku') IS DISTINCT FROM r.sku OR coalesce(v_prev -> 'faltas', '[]'::jsonb) <> '[]'::jsonb THEN
      RAISE EXCEPTION 'FALHOU: passo 8 — cat_prever_sku_modelo dá % para o produto com o SKU %.', v_prev, r.sku;
    END IF;
    v_n := v_n + 1;
  END LOOP;
  PERFORM set_config('request.jwt.claims', '', true);
  IF v_n <> 20 THEN RAISE EXCEPTION 'FALHOU: passo 8 — só % produtos comparados.', v_n; END IF;

  -- 9. a linha consolidada da auditoria
  IF NOT EXISTS (SELECT 1 FROM entity_audit_log e WHERE e.organization_id = c_org AND e.source = 'migration:resguardos_mudelar'
                 AND e.table_name = 'products' AND e.entity_id = v_sub AND (e.changed_fields ->> 'produtos')::integer = c_total) THEN
    RAISE EXCEPTION 'FALHOU: passo 9 — falta a linha consolidada da auditoria da importação.';
  END IF;
END $t$;

SELECT 'OK: resguardos da Mudelar (2541 produtos, 558 modelos) conferidos nos passos 0 a 9.' AS resultado;

ROLLBACK;
